ops.anchor:
/* ============ HEADER COMPACTO ============ */
.an-header--compact {
  position: sticky; top: 0; z-index: 100;
  background: var(--bg); border-bottom: 1px solid var(--bd-1);
}
.an-header--compact .an-utilbar {
  display: flex; justify-content: space-between; align-items: center;
  padding: 8px 16px; background: var(--bg-0); flex-wrap: wrap; gap: 8px;
}
.brand-compact { display: inline-flex; align-items: center; gap: 8px; }
.brand-logo-compact { width: 32px; height: 32px; object-fit: contain; border-radius: 6px; }
.brand-name {
  font-family: "Cinzel Decorative", serif; font-weight: 700; font-size: 1rem;
  color: var(--gn-gold); text-shadow: 0 0 4px rgba(255,230,180,0.4); white-space: nowrap;
}
@media (max-width: 900px) {
  .an-header--compact .an-utilbar { flex-direction: column; align-items: stretch; }
  .an-header--compact .an-util-left,
  .an-header--compact .an-util-right { flex-wrap: wrap; justify-content: center; }
  .brand-name { font-size: 0.9rem; }
}

ops.text:
/* ============ BARRA DE ARRIBA (BL-070 TOP-5) — conducta en js/gn-topbar.js ============ */
header.gn-tb { position: relative; z-index: 960; background: var(--bg-0); border-bottom: 1px solid var(--bd-1); }
.gn-tb__row { display: flex; align-items: center; gap: 12px; min-height: 56px; padding: 6px 16px; }
.gn-tb__id { display: flex; align-items: center; gap: 10px; min-width: 0; }
.gn-tb__brand { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; min-width: 0; border-radius: 10px; color: inherit; text-decoration: none; }
.brand-logo-compact { width: 32px; height: 32px; object-fit: contain; border-radius: 6px; flex-shrink: 0; }
.gn-tb__names { display: grid; line-height: 1.2; min-width: 0; }
.brand-name {
  font-family: "Cinzel Decorative", serif; font-weight: 700; font-size: 1rem;
  color: var(--gn-gold); text-shadow: 0 0 4px rgba(255,230,180,0.4); white-space: nowrap;
}
.gn-tb__fan { font-size: .72rem; color: var(--tx-2); white-space: nowrap; }
.gn-tb__dev { display: none; align-items: center; min-height: 22px; padding: 0 8px; border-radius: 999px; background: #F2B94B; color: #0F1117; font-size: .7rem; font-weight: 800; letter-spacing: .08em; }
html.gn-env-dev .gn-tb__dev { display: inline-flex; }
.gn-tb__acct { display: flex; align-items: center; gap: 8px; min-width: 0; margin: 0 auto; }
.gn-tb #keySelectGlobal { min-height: 38px; max-width: 260px; padding: 0 12px; border: 1px solid var(--bd-1); border-radius: 999px; background-color: var(--bg-1); color: var(--tx-1); font: inherit; font-size: .88rem; cursor: pointer; }
.gn-tb__tools { display: flex; align-items: center; gap: 4px; }
.gn-tb__btn { display: inline-flex; align-items: center; gap: 6px; min-height: 38px; padding: 0 10px; border: 1px solid transparent; border-radius: 10px; background: transparent; color: var(--tx-2); font: inherit; font-size: .88rem; text-decoration: none; white-space: nowrap; cursor: pointer; }
.gn-tb__btn:hover, .gn-tb__btn[aria-expanded="true"] { background: var(--bg-1); border-color: var(--bd-1); color: var(--tx-1); }
.gn-tb__btn img, .gn-tb__btn svg { width: 18px; height: 18px; object-fit: contain; flex-shrink: 0; }
.gn-tb a:focus-visible, .gn-tb button:focus-visible, .gn-tb select:focus-visible { outline: 2px solid var(--acc-1); outline-offset: 2px; }
.gn-tb__dd { position: relative; }
.gn-tb__menu { position: absolute; right: 0; top: calc(100% + 6px); z-index: 950; min-width: 260px; margin: 0; padding: 6px; list-style: none; background: var(--bg-1); border: 1px solid var(--bd-1); border-radius: 12px; box-shadow: 0 12px 30px rgba(0,0,0,.4); }
.gn-tb__menu[hidden] { display: none; }
.gn-tb__menu li { margin: 0; }
.gn-tb__menu [role="menuitem"] { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 44px; padding: 0 12px; border: 0; border-radius: 8px; background: transparent; color: var(--tx-1); opacity: 1; font: inherit; font-size: .9rem; text-align: left; text-decoration: none; cursor: pointer; }
.gn-tb__menu [role="menuitem"]:hover, .gn-tb__menu [role="menuitem"]:focus { background: var(--bg-2); }
.gn-tb__menu [role="menuitem"]:focus-visible { outline: 2px solid var(--acc-1); outline-offset: -2px; }
.gn-tb__menu img { width: 20px; height: 20px; object-fit: contain; }
.gn-tb__ext { margin-left: auto; color: var(--tx-2); }
.gn-tb__more { display: none; }
.footer-inner { flex-wrap: wrap; }
.footer-inner > a[href="https://pablosnchz.github.io/bio/"] { margin-left: auto; }
@media (max-width: 900px) {
  .gn-tb__row { gap: 8px; padding: 6px 10px; }
  .gn-tb__acct { flex: 1; margin: 0; }
  .gn-tb #keySelectGlobal { flex: 1; width: 100%; max-width: none; min-height: 44px; }
  .gn-tb__btn { min-height: 44px; }
  .gn-tb__acct .gn-tb__btn, .gn-tb__more { justify-content: center; width: 44px; padding: 0; }
  .gn-tb__more { display: inline-flex; }
  .gn-tb__tools { display: none; position: absolute; left: 8px; right: 8px; top: calc(100% + 4px); z-index: 950; flex-direction: column; align-items: stretch; gap: 4px; max-height: calc(100vh - 80px); overflow: auto; padding: 8px; background: var(--bg-1); border: 1px solid var(--bd-1); border-radius: 14px; box-shadow: 0 14px 34px rgba(0,0,0,.45); }
  .gn-tb.is-open .gn-tb__tools { display: flex; }
  .gn-tb__tools .gn-tb__btn { width: 100%; justify-content: flex-start; }
  .gn-tb__menu { position: static; min-width: 0; padding: 0 0 0 14px; border: 0; background: transparent; box-shadow: none; }
}
@media (max-width: 600px) {
  .gn-tb__names, .gn-tb__lbl { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
}
